use pony_agent_core::agent::session::{HistoryMessageKind, HistoryNodeKind, SessionStore, TurnTraceRecord};
fn t(id: &str) -> TurnTraceRecord { TurnTraceRecord { turn_id: id.into(), session_id: Some("s1".into()), ..Default::default() } }
fn main() {
    let mut s = SessionStore::memory_only();
    s.append_turn_with_kind(Some("s1"), "q1", "a1", None, vec![], None, Some("turn-1"));
    s.record_turn_trace_in_memory(Some("s1"), t("turn-1"));
    s.append_turn_with_kind(Some("s1"), "q2", "a2 中断", None, vec![], Some(HistoryMessageKind::Cancelled), Some("turn-2"));
    s.record_turn_trace_in_memory(Some("s1"), t("turn-3")); // B1 事故时序：新轮 trace 先到、head 仍是旧节点
    let st = s.get_session("s1").unwrap().clone();
    for n in &st.history_nodes { println!("{:?} turn_id={:?}", n.kind, n.turn_id); }
    assert_eq!(st.history_nodes.iter().find(|n| matches!(n.kind, HistoryNodeKind::TurnCommitted)).unwrap().turn_id.as_deref(), Some("turn-1"));
    assert_eq!(st.history_nodes.iter().find(|n| matches!(n.kind, HistoryNodeKind::TurnCancelled)).unwrap().turn_id.as_deref(), Some("turn-2"));
    assert_eq!(st.history_cursor.branch_head_node_id, st.history_cursor.visible_node_id);
    println!("B1_OK: committed 保 turn-1 / cancelled 保 turn-2 / turn-3 无主 / head==visible");
}
RS
RLIB=$(ls target/debug/deps/libpony_agent_core-*.rlib | head -1); rustc --edition 2021 /tmp/rb1.rs --extern pony_agent_core=$RLIB -L dependency=target/debug/deps -o /tmp/rb1 && /tmp/rb1

